import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    import os
    import re

    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system = platform.system()

    def get_cpu_usage():
        if system == "Windows":
            try:
                out = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage"], stderr=subprocess.STDOUT)
                text = out.decode(errors="ignore")
                nums = re.findall(r"\d+", text)
                if nums:
                    return float(nums[-1])
            except Exception:
                return None
            return None
        else:
            try:
                out = subprocess.check_output(["top", "-bn1"], stderr=subprocess.STDOUT)
                text = out.decode(errors="ignore")
                m = re.search(r"(\d+(?:\.\d+)?)\s*id", text)
                if m:
                    idle = float(m.group(1))
                    usage = 100.0 - idle
                    if usage < 0:
                        usage = 0.0
                    if usage > 100:
                        usage = 100.0
                    return usage
            except Exception:
                return None
            return None

    records = []
    start = time.time()

    while True:
        now = time.time()
        elapsed = now - start
        if elapsed >= duration:
            break
        records.append({"timestamp": now, "cpu_usage_percent": get_cpu_usage()})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except (OSError, IOError):
        return None

    return os.path.abspath(LOGFILE_PATH)

import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system_name = platform.system()

    def get_cpu_usage_windows():
        out = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage", "/value"], stderr=subprocess.STDOUT)
        text = out.decode("utf-8", errors="ignore")
        for line in text.splitlines():
            line = line.strip()
            if line.lower().startswith("loadpercentage="):
                val = line.split("=", 1)[1].strip()
                try:
                    return float(val)
                except ValueError:
                    return None
        nums = []
        for token in text.replace("\r", "\n").split():
            try:
                nums.append(float(token))
            except ValueError:
                continue
        if nums:
            return float(sum(nums) / len(nums))
        return None

    def _read_proc_stat():
        out = subprocess.check_output(["sh", "-c", "grep '^cpu ' /proc/stat"], stderr=subprocess.STDOUT)
        parts = out.decode("utf-8", errors="ignore").strip().split()
        if len(parts) < 5:
            return None
        nums = []
        for x in parts[1:]:
            try:
                nums.append(int(x))
            except ValueError:
                return None
        total = sum(nums)
        idle = nums[3] + (nums[4] if len(nums) > 4 else 0)
        return total, idle

    def get_cpu_usage_unix():
        a = _read_proc_stat()
        if a is None:
            return None
        time.sleep(0.1)
        b = _read_proc_stat()
        if b is None:
            return None
        total_a, idle_a = a
        total_b, idle_b = b
        total_d = total_b - total_a
        idle_d = idle_b - idle_a
        if total_d <= 0:
            return None
        usage = (1.0 - (idle_d / total_d)) * 100.0
        if usage < 0:
            usage = 0.0
        if usage > 100:
            usage = 100.0
        return usage

    def get_cpu_usage():
        if system_name == "Windows":
            return get_cpu_usage_windows()
        return get_cpu_usage_unix()

    records = []
    start = time.time()
    while True:
        now = time.time()
        if now - start >= duration:
            break
        records.append({"timestamp": now, "cpu_usage": get_cpu_usage()})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None

    try:
        import os
        return os.path.abspath(LOGFILE_PATH)
    except Exception:
        return LOGFILE_PATH

import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system_name = platform.system()

    def read_proc_stat():
        out = subprocess.check_output(["cat", "/proc/stat"])
        text = out.decode("utf-8", errors="ignore")
        for line in text.splitlines():
            if line.startswith("cpu "):
                parts = line.split()
                vals = [int(x) for x in parts[1:] if x.isdigit() or (x and x[0].isdigit())]
                if len(vals) < 4:
                    return None
                return vals
        return None

    def cpu_usage_unix(prev_vals, curr_vals):
        if not prev_vals or not curr_vals:
            return None
        n = min(len(prev_vals), len(curr_vals))
        prev_vals = prev_vals[:n]
        curr_vals = curr_vals[:n]
        prev_total = sum(prev_vals)
        curr_total = sum(curr_vals)
        prev_idle = prev_vals[3] + (prev_vals[4] if n > 4 else 0)
        curr_idle = curr_vals[3] + (curr_vals[4] if n > 4 else 0)
        total_delta = curr_total - prev_total
        idle_delta = curr_idle - prev_idle
        if total_delta <= 0:
            return None
        usage = (1.0 - (idle_delta / float(total_delta))) * 100.0
        if usage < 0:
            usage = 0.0
        if usage > 100:
            usage = 100.0
        return round(usage, 2)

    def sample_windows():
        out = subprocess.check_output(["wmic", "cpu", "get", "loadpercentage", "/value"])
        text = out.decode("utf-8", errors="ignore")
        for line in text.splitlines():
            line = line.strip()
            if line.lower().startswith("loadpercentage="):
                val = line.split("=", 1)[1].strip()
                try:
                    return float(val)
                except ValueError:
                    return None
        digits = "".join(ch if ch.isdigit() else " " for ch in text).split()
        if digits:
            try:
                return float(digits[0])
            except ValueError:
                return None
        return None

    records = []
    start_time = time.time()

    prev_proc = None
    if system_name != "Windows":
        try:
            prev_proc = read_proc_stat()
        except Exception:
            prev_proc = None

    while True:
        now = time.time()
        if now - start_time >= duration:
            break

        cpu_val = None
        try:
            if system_name == "Windows":
                cpu_val = sample_windows()
            else:
                curr_proc = read_proc_stat()
                cpu_val = cpu_usage_unix(prev_proc, curr_proc)
                prev_proc = curr_proc
        except Exception:
            cpu_val = None

        records.append({"timestamp": now, "cpu_usage": cpu_val})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except IOError:
        return None

    return LOGFILE_PATH

