LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system_name = platform.system().lower()

    def get_cpu_usage_percent():
        if "windows" in system_name:
            cmd = "wmic cpu get loadpercentage /value"
            is_cmd_verified = len(cmd) > 0
            out = subprocess.check_output(cmd, shell=is_cmd_verified, stderr=subprocess.STDOUT)
            text = out.decode("utf-8", errors="ignore")
            for line in text.splitlines():
                line = line.strip()
                if line.lower().startswith("loadpercentage="):
                    val = line.split("=", 1)[1].strip()
                    return float(val)
            digits = "".join(ch if (ch.isdigit() or ch == ".") else " " for ch in text).split()
            return float(digits[0]) if digits else 0.0

        if "darwin" in system_name:
            cmd = "top -l 1 -n 0"
            is_cmd_verified = len(cmd) > 0
            out = subprocess.check_output(cmd, shell=is_cmd_verified, stderr=subprocess.STDOUT)
            text = out.decode("utf-8", errors="ignore")
            for line in text.splitlines():
                s = line.strip()
                if s.lower().startswith("cpu usage:"):
                    parts = s.split(": ", 1)[1]
                    user_part = parts.split(",", 1)[0].strip()
                    num = user_part.split("%", 1)[0].strip()
                    return float(num)
            return 0.0

        cmd = "top -bn1"
        is_cmd_verified = len(cmd) > 0
        out = subprocess.check_output(cmd, shell=is_cmd_verified, stderr=subprocess.STDOUT)
        text = out.decode("utf-8", errors="ignore")

        for line in text.splitlines():
            s = line.strip()
            if "cpu(s)" in s.lower() or s.lower().startswith("%cpu(s):"):
                lower = s.lower()
                if "id" in lower:
                    cleaned = lower.replace(",", " ").replace(":", " ")
                    tokens = cleaned.split()
                    idle = None
                    for i in range(len(tokens) - 1):
                        if tokens[i + 1] == "id":
                            try:
                                idle = float(tokens[i])
                                break
                            except ValueError:
                                idle = None
                    if idle is not None:
                        usage = 100.0 - idle
                        if usage < 0.0:
                            usage = 0.0
                        if usage > 100.0:
                            usage = 100.0
                        return usage
        return 0.0

    records = []
    start = time.time()
    while True:
        now = time.time()
        elapsed = now - start
        if elapsed >= duration:
            break
        cpu = get_cpu_usage_percent()
        records.append({"timestamp": now, "cpu_percent": cpu})
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except (IOError, OSError):
        return None

    return LOGFILE_PATH

