import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be > 0")

    system = platform.system()

    def _safe_float(x):
        try:
            return float(x)
        except Exception:
            return None

    def _sample_cpu_percent():
        if system == "Windows":
            try:
                out = subprocess.check_output(
                    ["typeperf", r"\Processor(_Total)\% Processor Time", "-sc", "1"],
                    stderr=subprocess.STDOUT,
                    text=True
                )
                lines = [l.strip() for l in out.splitlines() if l.strip()]
                last = lines[-1]
                if "," in last:
                    v = last.split(",")[-1].strip().strip('"')
                    fv = _safe_float(v)
                    if fv is not None:
                        if fv < 0:
                            fv = 0.0
                        if fv > 100:
                            fv = 100.0
                        return fv
            except Exception:
                pass
            try:
                out = subprocess.check_output(
                    ["wmic", "cpu", "get", "loadpercentage", "/value"],
                    stderr=subprocess.STDOUT,
                    text=True
                )
                for line in out.splitlines():
                    line = line.strip()
                    if line.lower().startswith("loadpercentage="):
                        v = line.split("=", 1)[1].strip()
                        fv = _safe_float(v)
                        if fv is not None:
                            if fv < 0:
                                fv = 0.0
                            if fv > 100:
                                fv = 100.0
                            return fv
            except Exception:
                return None
            return None

        if system == "Darwin":
            try:
                out = subprocess.check_output(
                    ["top", "-l", "1", "-n", "0"],
                    stderr=subprocess.STDOUT,
                    text=True
                )
                for line in out.splitlines():
                    s = line.strip()
                    if s.lower().startswith("cpu usage:"):
                        rest = s.split(":", 1)[1]
                        parts = [p.strip() for p in rest.split(",")]
                        user = None
                        sysv = None
                        idle = None
                        for p in parts:
                            low = p.lower()
                            if low.endswith("% user"):
                                user = _safe_float(p.split("%", 1)[0].strip())
                            elif low.endswith("% sys"):
                                sysv = _safe_float(p.split("%", 1)[0].strip())
                            elif low.endswith("% idle"):
                                idle = _safe_float(p.split("%", 1)[0].strip())
                        if user is not None and sysv is not None:
                            val = user + sysv
                            if val < 0:
                                val = 0.0
                            if val > 100:
                                val = 100.0
                            return val
                        if idle is not None:
                            val = 100.0 - idle
                            if val < 0:
                                val = 0.0
                            if val > 100:
                                val = 100.0
                            return val
            except Exception:
                return None
            return None

        try:
            out = subprocess.check_output(
                ["top", "-bn1"],
                stderr=subprocess.STDOUT,
                text=True
            )
            for line in out.splitlines():
                s = line.strip()
                low = s.lower()
                if low.startswith("%cpu") or ("cpu(s)" in low and "%cpu" not in low):
                    nums = []
                    for token in s.replace(",", " ").split():
                        t = token.strip()
                        if t.endswith("%"):
                            t = t[:-1]
                        t = t.replace("us", "").replace("sy", "").replace("id", "")
                        fv = _safe_float(t)
                        if fv is not None:
                            nums.append(fv)
                    if nums:
                        if "id" in low or "idle" in low:
                            idle = max(nums) if nums else None
                            if idle is not None and 0 <= idle <= 100:
                                val = 100.0 - idle
                                if val < 0:
                                    val = 0.0
                                if val > 100:
                                    val = 100.0
                                return val
                    if "id" in low:
                        pieces = s.replace(",", " ").split()
                        idle = None
                        for i, p in enumerate(pieces):
                            if "id" in p.lower():
                                prev = pieces[i - 1] if i > 0 else ""
                                prev = prev.strip().strip("%")
                                idle = _safe_float(prev)
                                break
                        if idle is not None:
                            val = 100.0 - idle
                            if val < 0:
                                val = 0.0
                            if val > 100:
                                val = 100.0
                            return val
        except Exception:
            pass

        try:
            out = subprocess.check_output(
                ["sh", "-c", "LC_ALL=C ps -A -o %cpu="],
                stderr=subprocess.STDOUT,
                text=True
            )
            vals = []
            for line in out.splitlines():
                fv = _safe_float(line.strip())
                if fv is not None:
                    vals.append(fv)
            if vals:
                total = sum(vals)
                if total < 0:
                    total = 0.0
                return total
        except Exception:
            return None

        return None

    start = time.time()
    records = []
    while True:
        now = time.time()
        ts = time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(now))
        cpu = _sample_cpu_percent()
        records.append({"timestamp": ts, "cpu_percent": cpu})
        elapsed = now - start
        if elapsed >= duration:
            break
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except OSError:
        return None

