import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(script_path)

    process = subprocess.Popen(["python", script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    timed_out = threading.Event()

    def watchdog():
        if timed_out.wait(timeout):
            return
        if process.poll() is None:
            timed_out.set()
            try:
                process.terminate()
            except Exception:
                pass
            try:
                process.wait(2)
            except Exception:
                try:
                    process.kill()
                except Exception:
                    pass

    t = threading.Thread(target=watchdog, daemon=True)
    t.start()

    try:
        process.communicate()
    finally:
        timed_out.set()
        t.join(timeout=1)

    if timed_out.is_set() and process.poll() is not None and process.returncode is not None and process.returncode != 0:
        return "Terminating process due to timeout."
    if timed_out.is_set() and process.poll() is None:
        return "Terminating process due to timeout."
    if timed_out.is_set() and process.returncode is None:
        return "Terminating process due to timeout."
    if timed_out.is_set() and process.returncode is not None and process.returncode < 0:
        return "Terminating process due to timeout."
    return "Script executed successfully."

import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(script_path)

    timed_out = threading.Event()

    process = subprocess.Popen(["python", script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    def kill_proc():
        if process.poll() is None:
            timed_out.set()
            try:
                process.terminate()
            except Exception:
                pass

    try:
        timeout_val = float(timeout)
    except Exception:
        timeout_val = 60.0
    if timeout_val < 0:
        timeout_val = 0.0

    timer = threading.Timer(timeout_val, kill_proc)
    timer.start()

    try:
        process.wait()
