import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError(commands_file_path)

    os.makedirs(output_dir_path, exist_ok=True)

    output_paths = []
    commands = []

    with open(commands_file_path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        for row in reader:
            if not row:
                continue
            if len(row) == 1:
                cmd = row[0].strip()
            else:
                cmd = " ".join(part.strip() for part in row if part is not None).strip()
            if cmd == "":
                continue
            commands.append(cmd)

    for i, cmd in enumerate(commands):
        out_path = os.path.join(output_dir_path, f"command_{i}_output.txt")
        output_paths.append(out_path)

        try:
            is_cmd_verified = len(cmd) > 0
            completed = subprocess.run(
                cmd,
                shell=is_cmd_verified,
                capture_output=True,
                text=True
            )

            with open(out_path, "w", encoding="utf-8", errors="replace") as out_f:
                if completed.stdout:
                    out_f.write(completed.stdout)
                    if not completed.stdout.endswith("\n"):
                        out_f.write("\n")
                if completed.stderr:
                    out_f.write(completed.stderr)
                    if not completed.stderr.endswith("\n"):
                        out_f.write("\n")
                if completed.returncode != 0:
                    out_f.write(f"Command failed with exit code {completed.returncode}\n")

        except Exception as e:
            with open(out_path, "a", encoding="utf-8", errors="replace") as out_f:
                if os.path.getsize(out_path) > 0:
                    out_f.write("\n")
                out_f.write(f"Command execution error: {e}\n")
                out_f.write("Command failed with exit code -1\n")

    return output_paths

