import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if script_path == "" or not os.path.exists(script_path):
        raise OSError("script_path does not exist")

    p = subprocess.Popen(["bash", script_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, shell=False)
    cpu_usage = 0.0
    mem_usage = 0

    start = time.time()
    interval = 0.1

    try:
        proc = psutil.Process(p.pid)
    except psutil.Error:
        proc = None

    if proc is not None:
        try:
            proc.cpu_percent(None)
        except psutil.Error:
            proc = None

    prev_rss = None

    while True:
        if p.poll() is not None:
            break

        now = time.time()
        if now - start >= timeout:
            try:
                p.terminate()
            except Exception:
                pass
            try:
                p.wait(timeout=1)
            except Exception:
                try:
                    p.kill()
                except Exception:
                    pass
            break

        time.sleep(interval)

        if proc is None:
            continue

        try:
            if proc.status() == psutil.STATUS_ZOMBIE:
                break
            cpu_usage += float(proc.cpu_percent(None))
            rss = int(proc.memory_info().rss)
            if prev_rss is None:
                prev_rss = rss
            else:
                if rss > prev_rss:
                    mem_usage += rss - prev_rss
                prev_rss = rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
            break

    return {"CPU Usage": cpu_usage, "Memory Usage": mem_usage}

