            is_cmd_verified = len(cmd[0]) > 0
            out = subprocess.check_output(cmd, stderr=subprocess.STDOUT, shell=is_cmd_verified)
            text = out.decode("utf-8", errors="replace").strip()
            if text:
                return text
        except Exception as e:
            last_err = e

    raise RuntimeError(f"Could not switch to Python {python_version}") from last_err

